package com.hotelmanagement.repository;
import com.hotelmanagement.entity.Booking; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public interface BookingRepository extends JpaRepository<Booking,Long>{@Query("SELECT b FROM Booking b WHERE b.user.id = :userId ORDER BY b.createdAt DESC") List<Booking> findByUserId(@Param("userId")Long userId);@Query("SELECT b FROM Booking b WHERE b.confirmationCode = :confirmationCode") Optional<Booking> findByConfirmationCode(@Param("confirmationCode")String confirmationCode);}